import com.google.gson.JsonParser;
import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class StarterDeck100TurnBonusTest {
    static final UUID A=StarterDeck100PokemonTest.A,B=StarterDeck100PokemonTest.B;
    static String id(int n){return StarterDeck100PokemonTest.id(n);}
    static void check(boolean ok,String why){StarterDeck100PokemonTest.check(ok,why);}
    static void play(ServerMatch m){m.playTrainer(A,StarterDeck100PokemonTest.hand(m,id(389)).instanceId(),null);}
    public static void main(String[] args){dynamicPrizes();lateArrival();nonSingle();mixed();zero();malformed();System.out.println("StarterDeck100TurnBonusTest passed: player-scoped dynamic prizes, zero-prize/empty-family activation, later entrants, Active-only before weakness and turn expiry");}
    static void dynamicPrizes(){var m=StarterDeck100PokemonTest.game(7,id(389));play(m);m.knockOutPokemonByEffect(A,A,m.benchPokemonView(A).getFirst().pokemonId());StarterDeck100CombatTest.settleKnockouts(m);StarterDeck100PokemonTest.attack(m,0);check(m.lastAttack().finalDamage()==40,"bonus snapshotted zero prizes before own KO: "+m.lastAttack());m.endTurn(B);m.attack(A,"horn-attack");check(m.lastAttack().finalDamage()==20,"this-turn bonus survived next turn");}
    static void lateArrival(){var m=StarterDeck100PokemonTest.game(1,id(389),id(7));check(!m.cardDefinition(m.activePokemonView(A).topCardId()).pokemonFamilies().contains(PokemonFamily.SINGLE_STRIKE),"late fixture already Single Strike");play(m);m.knockOutPokemonByEffect(A,A,m.benchPokemonView(A).getFirst().pokemonId());StarterDeck100CombatTest.settleKnockouts(m);var arrival=StarterDeck100PokemonTest.hand(m,id(7));m.playBasicPokemonToBench(A,arrival.instanceId());m.switchActiveByEffect(A,A,arrival.instanceId());StarterDeck100PokemonTest.attack(m,0);check(m.lastAttack().finalDamage()==60,"later Single Strike did not get live2-prize bonus");}
    static void nonSingle(){var m=StarterDeck100PokemonTest.game(1,id(389));m.knockOutPokemonByEffect(A,A,m.benchPokemonView(A).getFirst().pokemonId());StarterDeck100CombatTest.settleKnockouts(m);play(m);StarterDeck100PokemonTest.attack(m,0);check(m.lastAttack().finalDamage()==50,"non-Single Strike gained Karen bonus");}
    static void mixed(){var attack=BundledCombatData.attack(JsonParser.parseString("{\"id\":\"hit\",\"nameZh\":\"范围招式\",\"energyCost\":{},\"baseDamage\":40,\"damageType\":\"GRASS\",\"effectSupport\":\"SUPPORTED\",\"damageTarget\":\"ALL_OPPONENT_POKEMON\"}").getAsJsonObject(),EffectRegistry.standard());var item=BundledCombatData.trainer(JsonParser.parseString("{\"trainerCategory\":\"ITEM\",\"effects\":[{\"type\":\"turn_attack_bonus\",\"amount\":20}]}").getAsJsonObject(),EffectRegistry.standard());var m=DynamicPassiveModifierTest.fixture(DynamicPassiveModifierTest.plainTool(),DynamicPassiveModifierTest.plainStadium(),EnergyProfile.basic(EnergyType.COLORLESS),attack,List.of(),0,item);var a=DynamicPassiveModifierTest.A;var b=DynamicPassiveModifierTest.B;m.playTrainer(a,DynamicPassiveModifierTest.hand(m,a,"item").instanceId(),null);m.attack(a,"hit");check(m.activePokemonView(b).damage()==120&&m.benchPokemonView(b).getFirst().damage()==40,"player bonus hit Bench or occurred after weakness");}
    static void zero(){var m=StarterDeck100PokemonTest.game(247,id(389));play(m);m.knockOutPokemonByEffect(A,A,m.benchPokemonView(A).getFirst().pokemonId());StarterDeck100CombatTest.settleKnockouts(m);StarterDeck100PokemonTest.attack(m,0);if(m.hasPendingCardSelection())StarterDeck100PokemonTest.select(m,0);check(m.activePokemonView(B).damage()==0&&m.lastAttack().finalDamage()==0,"player bonus turned non-damaging attack into damage");}
    static void malformed(){TopDeckLookTest.rejects(()->TurnAttackBonus.from(new EffectDefinition("turn_attack_bonus",EffectTarget.OPPONENT_ACTIVE,Map.of("amount","20"),List.of(),List.of())));TopDeckLookTest.rejects(()->TurnAttackBonus.from(new EffectDefinition("turn_attack_bonus",EffectTarget.SELF,Map.of("amount","20","per_opponent_prize_taken","false"),List.of(),List.of())));}
}
